import java.util.*;
public class TakeMetro {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int stationsCount = scanner.nextInt();
        int maxStationIndex = scanner.nextInt();
        int initialStation = scanner.nextInt() - 1;
        long totalDuration = scanner.nextLong();

        while (totalDuration % stationsCount != 0) {
            if (initialStation < maxStationIndex) {
                initialStation = (int)((initialStation + totalDuration) % stationsCount);
            } else {
                initialStation = (int)((((initialStation - totalDuration) % stationsCount) + stationsCount) % stationsCount);
            }
            totalDuration--;
        }
        totalDuration /= stationsCount;

        int[] lastVisited = new int[stationsCount];
        Arrays.fill(lastVisited, -1);
        int stepCount = 0;
        lastVisited[initialStation] = stepCount;

        while (totalDuration-- > 0) {
            for (int i = stationsCount - 1; i > 0; i--) {
                if (initialStation < maxStationIndex) {
                    initialStation = (initialStation + i) % stationsCount;
                } else {
                    initialStation = (((initialStation - i) % stationsCount) + stationsCount) % stationsCount;
                }
            }
            stepCount++;
            if (lastVisited[initialStation] != -1) {
                totalDuration = totalDuration % (stepCount - lastVisited[initialStation]);
                lastVisited[initialStation] = stepCount;
            } else {
                lastVisited[initialStation] = stepCount;
            }
        }
        System.out.println(initialStation + 1);
    }
}
